from edcommon import *
KEEP={'STUDY GOAL','GRACE CONTROL','FAITH CONTROL','MYSTERY CONTROL','ACTS CONTROL'}
BND="Acts 28 establishes the suspension boundary; it does not by itself establish any further chronology, and this study does not reconstruct one."
def apply(els):
    rep(els,'When Israel reached its national judicial suspension at Acts 28, Paul declared','When Israel’s Prophecy Program was nationally suspended at Acts 28, Paul declared')
    rep(els,'That was national judicial suspension, not abolition and not a transfer; Israel’s promises stand.','That national suspension was not a cancellation, a transfer or an absorption. '+BND)
    rep(els,'That was a local turn, not Israel’s national judicial suspension;','That was a local turn, not the national suspension of Israel’s program;')
    rep(els,'Grace is always the ground of salvation. In Paul’s gospel, grace also sets the terms:','In Paul’s gospel, grace is the ground of salvation, and grace also sets the terms:')
    rep(els,' Grace is always the ground of salvation; in Paul’s gospel grace also sets the terms,',' In Paul’s gospel grace is the ground of salvation and also sets the terms,')
    return els
